package com.siestech.booksharing.Practical;
import android.Manifest; import android.content.Intent; import android.content.pm.PackageManager; import android.net.Uri; import android.os.Bundle; import android.telephony.SmsManager; import android.widget.EditText; import android.widget.Toast; import androidx.annotation.NonNull; import androidx.appcompat.app.AppCompatActivity; import androidx.core.app.ActivityCompat; import com.siestech.booksharing.R;
public class SmsActivity extends AppCompatActivity{private EditText phone,msg;private static final int SMS=91;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_sms);phone=findViewById(R.id.phoneInput);msg=findViewById(R.id.messageInput);findViewById(R.id.sendSmsBtn).setOnClickListener(v->send());}private void send(){String p=phone.getText().toString().trim(),m=msg.getText().toString().trim();if(p.isEmpty()||m.isEmpty()){Toast.makeText(this,"Enter phone and message",Toast.LENGTH_SHORT).show();return;}if(android.os.Build.VERSION.SDK_INT>=23&&ActivityCompat.checkSelfPermission(this,Manifest.permission.SEND_SMS)!=PackageManager.PERMISSION_GRANTED){ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.SEND_SMS},SMS);return;}try{SmsManager.getDefault().sendTextMessage(p,null,m,null,null);Toast.makeText(this,"SMS sent",Toast.LENGTH_SHORT).show();}catch(Exception e){Intent i=new Intent(Intent.ACTION_SENDTO, Uri.parse("smsto:"+Uri.encode(p)));i.putExtra("sms_body",m);startActivity(i);}}@Override public void onRequestPermissionsResult(int r,@NonNull String[] p,@NonNull int[] g){super.onRequestPermissionsResult(r,p,g);if(r==SMS&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)send();else Toast.makeText(this,"SMS permission denied",Toast.LENGTH_SHORT).show();}}
